/**
 * Business-hours arithmetic for helpdesk SLAs (spec §6.4): Mon–Fri 09:30–18:30 in the tenant
 * time zone (IST), excluding tenant holidays. Pure functions — no I/O, so they are unit tested.
 *
 * Instants are shifted into "local wall clock" milliseconds (UTC getters then read IST), the
 * walk happens day by day, and results are shifted back to real instants.
 */
export type BusinessCalendar = {
  /** Minutes after local midnight when the business day opens (09:30 → 570). */
  startMin: number;
  /** Minutes after local midnight when it closes (18:30 → 1110). */
  endMin: number;
  /** Working weekdays, 0 = Sunday. */
  workDays: number[];
  /** Local date keys ("2026-10-02") that are holidays. */
  holidays: Set<string>;
  /** Local offset from UTC in minutes (IST = 330). */
  offsetMin: number;
};

export const DEFAULT_CALENDAR: BusinessCalendar = { startMin: 570, endMin: 1110, workDays: [1, 2, 3, 4, 5], holidays: new Set(), offsetMin: 330 };

const MIN = 60_000;
const DAY = 86_400_000;

export function calendarWith(holidays: Iterable<string>, base: Partial<BusinessCalendar> = {}): BusinessCalendar {
  return { ...DEFAULT_CALENDAR, ...base, holidays: new Set(holidays) };
}

const toLocal = (d: Date, cal: BusinessCalendar) => d.getTime() + cal.offsetMin * MIN;
const fromLocal = (ms: number, cal: BusinessCalendar) => new Date(ms - cal.offsetMin * MIN);
const midnight = (localMs: number) => Math.floor(localMs / DAY) * DAY;
const keyOfLocal = (localMs: number) => new Date(midnight(localMs)).toISOString().slice(0, 10);

export function isBusinessDay(localMidnightMs: number, cal: BusinessCalendar): boolean {
  const dow = new Date(localMidnightMs).getUTCDay();
  return cal.workDays.includes(dow) && !cal.holidays.has(keyOfLocal(localMidnightMs));
}

/** Business minutes in one full working day (540 for 09:30–18:30). */
export const dayLength = (cal: BusinessCalendar = DEFAULT_CALENDAR) => cal.endMin - cal.startMin;

/** The instant itself when inside business hours, else the next opening. */
export function nextBusinessOpen(at: Date, cal: BusinessCalendar = DEFAULT_CALENDAR): Date {
  let t = toLocal(at, cal);
  for (let guard = 0; guard < 800; guard++) {
    const day = midnight(t);
    const open = day + cal.startMin * MIN;
    const close = day + cal.endMin * MIN;
    if (isBusinessDay(day, cal) && t < close) return fromLocal(Math.max(t, open), cal);
    t = day + DAY;
  }
  return at;
}

/**
 * Adds business minutes to an instant. A start outside business hours begins at the next
 * opening ("a ticket created at 20:00 starts its clock at 09:30 the next working day").
 */
export function addBusinessMinutes(start: Date, minutes: number, cal: BusinessCalendar = DEFAULT_CALENDAR): Date {
  let remaining = Math.max(0, minutes) * MIN;
  let t = toLocal(nextBusinessOpen(start, cal), cal);
  for (let guard = 0; guard < 4000; guard++) {
    const day = midnight(t);
    if (!isBusinessDay(day, cal)) {
      t = day + DAY + cal.startMin * MIN;
      continue;
    }
    const open = day + cal.startMin * MIN;
    const close = day + cal.endMin * MIN;
    if (t < open) t = open;
    if (t >= close) {
      t = day + DAY + cal.startMin * MIN;
      continue;
    }
    const avail = close - t;
    if (remaining <= avail) return fromLocal(t + remaining, cal);
    remaining -= avail;
    t = day + DAY + cal.startMin * MIN;
  }
  return fromLocal(t, cal);
}

/** Business minutes elapsed between two instants (0 when `to` ≤ `from`). */
export function businessMinutesBetween(from: Date, to: Date, cal: BusinessCalendar = DEFAULT_CALENDAR): number {
  const a = toLocal(from, cal);
  const b = toLocal(to, cal);
  if (b <= a) return 0;
  let total = 0;
  for (let day = midnight(a), guard = 0; day <= b && guard < 4000; day += DAY, guard++) {
    if (!isBusinessDay(day, cal)) continue;
    const open = day + cal.startMin * MIN;
    const close = day + cal.endMin * MIN;
    const s = Math.max(a, open);
    const e = Math.min(b, close);
    if (e > s) total += e - s;
  }
  return Math.floor(total / MIN);
}
